shader:
// PAIK/ABE COLORIZER - Portrait Mode
struct VertexOutput {
    @builtin(position) position: vec4<f32>,
    @location(0) uv: vec2<f32>,
};

struct Params {
    gain: f32, offset: f32, mix: f32, fold: f32,
    bias: f32, frequency: f32, phase: f32, threshold: f32,
    _pad0: f32, _pad1: f32, _pad2: f32, _pad3: f32,
    _pad4: f32, _pad5: f32, _pad6: f32, _pad7: f32,
};

@group(0) @binding(0) var input_texture: texture_2d<f32>;
@group(0) @binding(1) var input_sampler: sampler;
@group(0) @binding(2) var<uniform> params: Params;

fn to_luma(rgb: vec3<f32>) -> f32 {
    return dot(rgb, vec3<f32>(0.299, 0.587, 0.114));
}

fn video_clamp3(v: vec3<f32>) -> vec3<f32> {
    return clamp(v, vec3<f32>(0.0), vec3<f32>(1.0));
}

fn paik_abe_opamp_sat(v_in: f32, slew_factor: f32) -> f32 {
    let v_sat = 0.87;
    let gain = 3.0;
    let normalized = v_in * 2.0 - 1.0;
    var saturated = tanh(normalized * gain) / tanh(gain);
    let slew_smooth = 1.0 - slew_factor * 0.3;
    saturated = saturated * slew_smooth + normalized * (1.0 - slew_smooth);
    return (saturated + 1.0) * 0.5 * v_sat + (1.0 - v_sat) * 0.5;
}

fn paik_abe_fold(x: f32, gain: f32, depth: f32) -> f32 {
    var v = x * gain;
    let stages = u32(clamp(depth, 1.0, 5.0));
    for (var i = 0u; i < stages; i = i + 1u) {
        v = abs(fract(v * 0.5 + 0.25) * 2.0 - 1.0);
        v = v * 0.98 + 0.01;
    }
    return v;
}

@vertex
fn vs_main(@builtin(vertex_index) vertex_index: u32) -> VertexOutput {
    var positions = array<vec2<f32>, 3>(
        vec2<f32>(-1.0, -1.0), vec2<f32>(3.0, -1.0), vec2<f32>(-1.0, 3.0)
    );
    var uvs = array<vec2<f32>, 3>(
        vec2<f32>(0.0, 1.0), vec2<f32>(2.0, 1.0), vec2<f32>(0.0, -1.0)
    );
    var output: VertexOutput;
    output.position = vec4<f32>(positions[vertex_index], 0.0, 1.0);
    output.uv = uvs[vertex_index];
    return output;
}

@fragment
fn fs_main(input: VertexOutput) -> @location(0) vec4<f32> {
    let color = textureSample(input_texture, input_sampler, input.uv);
    let luma = to_luma(color.rgb);

    // Parameters
    let base_gain = params.gain * 3.0 + 1.0;
    let gain_r = base_gain;
    let gain_g = base_gain + 0.5;
    let gain_b = base_gain + 1.0;
    let fold_depth = params.offset * 3.0 + 1.0;
    let saturation = params.mix * 2.0;
    let slew = params.fold;

    // Fold each channel
    var r = paik_abe_fold(luma, gain_r, fold_depth);
    var g = paik_abe_fold(luma, gain_g, fold_depth);
    var b = paik_abe_fold(luma, gain_b, fold_depth);

    // Op-amp saturation
    r = paik_abe_opamp_sat(r, slew);
    g = paik_abe_opamp_sat(g, slew);
    b = paik_abe_opamp_sat(b, slew);

    // Saturation control
    let output_luma = (r + g + b) / 3.0;
    r = mix(output_luma, r, saturation);
    g = mix(output_luma, g, saturation);
    b = mix(output_luma, b, saturation);

    // Warmth
    r = r + 0.02;
    b = b - 0.01;

    return vec4<f32>(video_clamp3(vec3<f32>(r, g, b)), 1.0);
}
